--
-- Name: v_auth_user_effective_permissions; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_auth_user_effective_permissions AS
 WITH role_grants AS (
         SELECT ur.user_id,
            rp.permission_id,
            true AS granted_by_role
           FROM (public.auth_user_roles ur
             JOIN public.auth_role_permissions rp ON ((rp.role_id = ur.role_id)))
        ), user_overrides AS (
         SELECT auth_user_permission_overrides.user_id,
            auth_user_permission_overrides.permission_id,
            max(
                CASE
                    WHEN (auth_user_permission_overrides.effect = 'allow'::text) THEN 1
                    ELSE 0
                END) AS has_allow,
            max(
                CASE
                    WHEN (auth_user_permission_overrides.effect = 'deny'::text) THEN 1
                    ELSE 0
                END) AS has_deny
           FROM public.auth_user_permission_overrides
          GROUP BY auth_user_permission_overrides.user_id, auth_user_permission_overrides.permission_id
        ), all_candidates AS (
         SELECT role_grants.user_id,
            role_grants.permission_id
           FROM role_grants
        UNION
         SELECT user_overrides.user_id,
            user_overrides.permission_id
           FROM user_overrides
        )
 SELECT c.user_id,
    c.permission_id,
    pk.key AS permission_key,
    pk.label AS permission_label,
    pk.module,
    pk.scope,
        CASE
            WHEN (COALESCE(uo.has_deny, 0) = 1) THEN false
            WHEN (COALESCE(uo.has_allow, 0) = 1) THEN true
            WHEN (rg.granted_by_role IS TRUE) THEN true
            ELSE false
        END AS is_allowed,
        CASE
            WHEN (COALESCE(uo.has_deny, 0) = 1) THEN 'user-deny'::text
            WHEN (COALESCE(uo.has_allow, 0) = 1) THEN 'user-allow'::text
            WHEN (rg.granted_by_role IS TRUE) THEN 'role'::text
            ELSE 'none'::text
        END AS source
   FROM (((all_candidates c
     JOIN public.auth_permission_keys pk ON ((pk.id = c.permission_id)))
     LEFT JOIN role_grants rg ON (((rg.user_id = c.user_id) AND (rg.permission_id = c.permission_id))))
     LEFT JOIN user_overrides uo ON (((uo.user_id = c.user_id) AND (uo.permission_id = c.permission_id))));


ALTER VIEW public.v_auth_user_effective_permissions OWNER TO postgres;

